        .camera-halo{background:radial-gradient(circle,rgba(102,227,209,.15),rgba(102,227,209,.02) 50%,transparent 70%)}.lens-glass{background:radial-gradient(circle at 36% 31%,rgba(255,255,255,.8) 0 1%,rgba(137,255,211,.32) 2%,transparent 8%),radial-gradient(circle at 58% 64%,rgba(102,227,209,.62),transparent 21%),radial-gradient(circle at 42% 41%,#1f4b48,#0c2928 40%,#020403 68%)}.orbit-dot{display:none}.orbit{transform-style:preserve-3d}.orbit-particle{position:absolute;inset:-1px;border-radius:50%;animation:orbit-path 8s linear infinite}.orbit-particle::after{content:'';position:absolute;left:calc(50% - 6px);top:-6px;width:12px;height:12px;border-radius:50%;background:var(--acid);box-shadow:0 0 8px var(--acid),0 0 24px rgba(201,255,69,.8)}.orbit-particle.two{animation-delay:-4s;animation-duration:10s;animation-direction:reverse}.orbit-particle.two::after{width:9px;height:9px;left:calc(50% - 4.5px);top:-4.5px;background:var(--aqua);box-shadow:0 0 8px var(--aqua),0 0 22px rgba(102,227,209,.8)}
        .camera-stage{cursor:crosshair;outline:none}.camera-stage:focus-visible::after{content:'';position:absolute;inset:35px;border:1px dashed var(--aqua);border-radius:50%;opacity:.6}.capture-hint{position:absolute;z-index:7;right:4%;bottom:7%;display:flex;align-items:center;gap:9px;color:#777d75;font:500 8px/1 'DM Mono';letter-spacing:.14em;text-transform:uppercase}.capture-hint::before{content:'';width:18px;height:18px;border:1px solid rgba(255,255,255,.18);border-radius:50%;box-shadow:inset 0 0 0 5px rgba(102,227,209,.08)}.capture-flash{position:absolute;z-index:6;inset:5%;pointer-events:none;opacity:0;border-radius:50%;background:radial-gradient(circle at 50% 50%,rgba(255,255,255,.98) 0 4%,rgba(178,255,234,.72) 8%,rgba(102,227,209,.15) 31%,transparent 66%);mix-blend-mode:screen}.capture-card{position:absolute;z-index:8;left:50%;top:50%;width:112px;height:142px;padding:7px 7px 23px;pointer-events:none;opacity:0;background:#f0eee6;box-shadow:0 24px 55px rgba(0,0,0,.58);transform:translate(-50%,-50%) scale(.05);transform-style:preserve-3d}.capture-card::after{content:attr(data-label);position:absolute;left:8px;bottom:7px;color:#161916;font:500 6px/1 'DM Mono';letter-spacing:.09em}.capture-card i{display:block;width:100%;height:100%;background-position:center;background-size:cover}.capture-card.one i{background-image:url('https://images.unsplash.com/photo-1519225421980-715cb0215aed?auto=format&fit=crop&q=82&w=400')}.capture-card.two i{background-image:url('https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&q=82&w=400')}.capture-card.three i{background-image:url('https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&q=82&w=400')}.camera-stage.capturing .capture-flash{animation:shutter-flash .72s ease-out}.camera-stage.capturing .capture-card.one{animation:capture-one 1.8s cubic-bezier(.15,.75,.2,1)}.camera-stage.capturing .capture-card.two{animation:capture-two 1.8s .08s cubic-bezier(.15,.75,.2,1)}.camera-